/**
 * Created by My PC on 03/10/2016.
 */

import java.util.*;

public class P2 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int length = input.nextInt();
        input.nextLine();
        String str = input.nextLine();

        int maxLength = 0;
        int countLength = 0;
        int countWord = 0;
        int checker = 0;
        int checkerInside = 0;
        boolean isInWordOut = false;
        boolean isInWordIn = false;
        boolean isInside = false;

        int index = 0;

        while (index < length)
        {
            if (str.charAt(index) == '(')
            {
                isInside = true;
                checkerInside++;
                if (maxLength < countLength)
                    maxLength = countLength;
                countLength = 0;
                isInWordOut = false;
            }
            else if (str.charAt(index) == ')')
            {
                isInside = false;
                checkerInside = 0;
                if (checker > 0)
                {
                    countWord++;
                    checker = 0;
                }
            }
            else
            {
                if (checkerInside > 0)
                {
                    isInside = true;
                }
            }

            if (index == length)
                break;

            if (str.charAt(index) != ')' & str.charAt(index) != '(')
            {
                if (!isInside)
                {
                    if (str.charAt(index) == '_')
                    {
                        if (maxLength < countLength)
                            maxLength = countLength;
                        countLength = 0;
                        isInWordOut = false;
                    }
                    else isInWordOut = true;

                    if (isInWordOut)
                    {
                        countLength++;
                    }
                }
                else
                {
                    isInWordOut = false;
                    if (str.charAt(index) == '_')
                    {
                        if (checker > 0)
                            countWord++;
                        checker = 0;
                        isInWordIn = false;
                    }
                    else isInWordIn = true;

                    if(isInWordIn)
                    {
                        checker++;
                    }
                }
            }

            index++;
        }

        if (maxLength < countLength)
            maxLength = countLength;

        System.out.println(maxLength + " " + countWord);

    }
}

